window.OVA_CONTENT={"slug":"seccion-02-indicadores-y-gestion-ambiental","title":"Indicadores y gestión ambiental","minutes":40,"summary":"Interpreta indicadores biológicos y evalúa compostaje, biorremediación, agua, suelo y economía circular.","objective":"Seleccionar evidencia y prácticas sostenibles según el problema ambiental y sus límites.","stages":[{"eyebrow":"Bioindicación","title":"1. Organismos que informan","reading":"Un indicador biológico utiliza presencia, ausencia, abundancia o respuesta de organismos para aportar información sobre condiciones ambientales. Complementa mediciones físicas y químicas.","application":"Un organismo aislado no explica todo el ecosistema; importan sensibilidad, muestreo, temporalidad y referencia.","activity":{"type":"choice","question":"¿Qué uso es correcto?","options":["Integrar el indicador con otras mediciones","Declarar el estado total con una sola observación","Omitir el contexto del muestreo"],"answer":[0],"success":"La bioindicación aporta una línea de evidencia."}},{"eyebrow":"Prácticas","title":"2. Alternativas con propósitos distintos","reading":"El compostaje transforma residuos orgánicos; la biorremediación usa organismos para contribuir al tratamiento de contaminantes; la reutilización de agua reduce demanda cuando la calidad es adecuada.","application":"Cada alternativa exige caracterización del material, condiciones operativas y control del resultado.","activity":{"type":"match","question":"Relaciona práctica y propósito.","pairs":[{"label":"Compostaje","value":"organicos","option":"Estabilizar residuos orgánicos"},{"label":"Biorremediación","value":"contaminantes","option":"Tratar ciertos contaminantes"},{"label":"Reúso de agua","value":"demanda","option":"Reducir demanda de agua nueva"}],"answer":["organicos","contaminantes","demanda"],"success":"No todas las prácticas resuelven el mismo problema."}},{"eyebrow":"Residuos","title":"3. De residuo a recurso","reading":"La economía circular busca mantener materiales en uso, pero un residuo solo puede convertirse en recurso si su composición, inocuidad, volumen, logística y mercado lo permiten.","application":"El aprovechamiento también consume energía, agua y otros insumos que deben incluirse en la evaluación.","activity":{"type":"order","question":"Ordena la evaluación de una alternativa.","items":["Caracterizar el residuo","Definir transformación posible","Estimar insumos y controles","Evaluar producto y mercado","Comparar impactos y viabilidad"],"answer":[0,1,2,3,4],"success":"Circularidad requiere evidencia material y económica."}},{"eyebrow":"Agua y suelo","title":"4. Variables para una gestión racional","reading":"La cantidad de agua, su calidad, los puntos de consumo, las pérdidas y los efluentes determinan oportunidades de ahorro y reúso. En suelo importan estructura, materia orgánica, nutrientes y riesgo de erosión.","application":"Las metas deben vincularse con indicadores medibles y condiciones del proceso.","activity":{"type":"multi","question":"Selecciona datos necesarios para gestionar agua.","options":["Consumo por etapa","Calidad requerida","Volumen y calidad de efluentes","Color de las tuberías sin plano"],"answer":[0,1,2],"success":"Medir cantidad y calidad permite priorizar."}},{"eyebrow":"Caso aplicado","title":"5. Cáscaras y pulpa de fruta","reading":"Una procesadora genera cáscaras y pulpa con alta humedad. Antes de decidir entre compostaje, alimentación, extracción de compuestos o bioenergía debe conocer composición, estabilidad, volumen y riesgos.","application":"La alternativa más llamativa no siempre es la más viable para la escala local.","activity":{"type":"choice","question":"¿Cuál es el primer paso?","options":["Caracterizar el residuo y su variabilidad","Comprar tecnología sin datos","Asumir que todo residuo orgánico es seguro"],"answer":[0],"success":"La caracterización define opciones reales."}}],"number":"02","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};